import '../history/history_xi.dart';
import '../intents/finance_intent.dart';
import '../intents/finance_repository.dart';

/// Opt-in, server-fenced candidate. Not an AuthGate integration or live gate.
/// The epoch is supplied by an authoritative provisioner, never generated by a
/// device clock. Logout-all, transfer and relogin must advance it atomically.
class FinanceSessionXiiiBinding {
  final String ownerUid, teamId;
  final int epoch;
  FinanceSessionXiiiBinding({required this.ownerUid, required this.teamId,
    required this.epoch}) {
    for (final id in [ownerUid, teamId]) {
      if (id.isEmpty || id.length > 128 || id.contains('/')) {
        throw const FormatException('session_xiii_invalid_binding');
      }
    }
    if (epoch < 1 || epoch > 9007199254740991) {
      throw const FormatException('session_xiii_invalid_epoch');
    }
  }
  String get fencePath => 'financeSessionEpochXiii/$ownerUid';
  Map<String, Object?> toMap() => {'ownerUid': ownerUid, 'teamId': teamId,
    'epoch': epoch};
  bool accepts(Map<String, Object?>? fence) => fence != null &&
    fence.length == 4 && fence['ownerUid'] == ownerUid &&
    fence['teamId'] == teamId && fence['epoch'] == epoch &&
    fence['epoch'] is int && fence['enabled'] == true;
}

/// Persist THIS envelope for fenced execution. An old raw XI pending intent
/// must never be silently rebound to a newer epoch. The XI digest is unchanged.
class FinanceSessionXiiiIntent {
  final HistoryXiIntent history;
  final FinanceSessionXiiiBinding binding;
  FinanceSessionXiiiIntent({required this.history, required this.binding}) {
    if (history.receipt.actorUid != binding.ownerUid ||
        history.receipt.teamId != binding.teamId) {
      throw const FormatException('session_xiii_identity_mismatch');
    }
  }
  String get permitPath => 'financeSessionXiii/${history.summaryPath.split('/').last}'
    '/permits/${history.receipt.operationId}';
  Map<String, Object?> permit() => {'version': 1, ...binding.toMap(),
    'operationId': history.receipt.operationId, 'historyDigest': history.digest,
    'summaryPath': history.summaryPath, 'rowPath': history.rowPath};
  String encode() => canonicalFinanceJson({'format': 'AndiSessionXiii',
    'version': 1, 'binding': binding.toMap(), 'history': history.encode()});
  factory FinanceSessionXiiiIntent.decode(String raw) {
    final d = decodeCanonicalFinanceJson(raw);
    if (d is! Map || d.length != 4 || d['format'] != 'AndiSessionXiii' ||
        d['version'] != 1 || d['history'] is! String || d['binding'] is! Map) {
      throw const FormatException('session_xiii_envelope_required');
    }
    final b = d['binding'] as Map;
    if (b.length != 3 || b['ownerUid'] is! String || b['teamId'] is! String ||
        b['epoch'] is! int) throw const FormatException('session_xiii_bad_binding');
    final result = FinanceSessionXiiiIntent(history: HistoryXiIntent.decode(d['history'] as String),
      binding: FinanceSessionXiiiBinding(ownerUid: b['ownerUid'] as String,
        teamId: b['teamId'] as String, epoch: b['epoch'] as int));
    if (result.encode() != raw) throw const FormatException('session_xiii_noncanonical');
    return result;
  }
}

/// Enforces the fence read in EACH retry of the underlying atomic transaction.
/// Security requires companion rules: a client-side read alone is insufficient.
/// A permit is immutable and committed together with the unchanged XI pair.
class FinanceSessionXiiiPort implements FinanceAtomicPort {
  final FinanceAtomicPort inner;
  final FinanceSessionXiiiIntent intent;
  final bool Function() sessionIsCurrent;
  bool _open = true;
  FinanceSessionXiiiPort({required this.inner, required this.intent,
    required this.sessionIsCurrent});
  void dispose() { _open = false; }
  void _guard() {
    if (_open) {
      try { if (!sessionIsCurrent()) _open = false; } catch (_) { _open = false; }
    }
    if (!_open) throw const FinanceRefusal('session_xiii_expired');
  }
  @override Future<T> atomic<T>(Future<T> Function(FinanceTransaction tx) action) async {
    _guard();
    final result = await inner.atomic((tx) async {
      _guard();
      final fence = await tx.read(intent.binding.fencePath); _guard();
      if (!intent.binding.accepts(fence)) throw const FinanceRefusal('session_xiii_fenced');
      final oldPermit = await tx.read(intent.permitPath); _guard();
      if (oldPermit != null && !sameFinanceValue(oldPermit, intent.permit())) {
        throw const FinanceRevisionConflict();
      }
      final buffered = _SessionTransaction(tx, intent, _guard);
      final value = await action(buffered); _guard();
      if (buffered.writes.isEmpty) {
        // Exact repository replay requires the matching historic permit too.
        if (oldPermit == null) throw StateError('session_xiii_missing_permit');
      } else {
        if (oldPermit != null || buffered.writes.length != 2 ||
            !sameFinanceValue(buffered.writes[intent.history.rowPath], intent.history.row()) ||
            !buffered.writes.containsKey(intent.history.summaryPath)) {
          throw const FinanceRefusal('session_xiii_invalid_pair');
        }
        final summary = buffered.writes[intent.history.summaryPath]!;
        validateHistoryXiSummary(summary, intent.history);
        if (summary['revision'] != intent.history.receipt.baseRevision + 1 ||
            summary['lastOperationId'] != intent.history.receipt.operationId) {
          throw const FinanceRefusal('session_xiii_invalid_pair');
        }
        _guard();
        for (final entry in buffered.writes.entries) { tx.write(entry.key, entry.value); }
        tx.write(intent.permitPath, intent.permit());
      }
      return value;
    });
    // An expiry here cannot retract a commit. Repository reports uncertainty.
    _guard(); return result;
  }
  @override Future<FinanceServerObservation> readServer(String path) async {
    _guard();
    if (path != intent.history.rowPath && path != intent.history.summaryPath) {
      throw const FinanceRefusal('session_xiii_read_scope');
    }
    final permit = await inner.readServer(intent.permitPath); _guard();
    if (permit.fromCache || permit.pendingWrites ||
        !sameFinanceValue(permit.data, intent.permit())) {
      throw const FinanceRefusal('session_xiii_unproven');
    }
    // No current-epoch equality here: a pre-revocation commit is still evidence.
    // Server rules must separately authorize current read access to this team.
    final result = await inner.readServer(path); _guard(); return result;
  }
}

class _SessionTransaction implements FinanceTransaction {
  final FinanceTransaction inner;
  final FinanceSessionXiiiIntent intent;
  final void Function() guard;
  final writes = <String, Map<String, Object?>>{};
  _SessionTransaction(this.inner, this.intent, this.guard);
  @override Future<Map<String, Object?>?> read(String path) async {
    guard();
    if (writes.isNotEmpty || ![intent.history.rowPath, intent.history.summaryPath,
        intent.history.receipt.targetPath].contains(path)) {
      throw const FinanceRefusal('session_xiii_transaction_scope');
    }
    final result = await inner.read(path); guard(); return result;
  }
  @override void write(String path, Map<String, Object?> value) {
    guard();
    if (![intent.history.rowPath, intent.history.summaryPath].contains(path) || writes.containsKey(path)) {
      throw const FinanceRefusal('session_xiii_write_scope');
    }
    writes[path] = freezeFinanceValue(value) as Map<String, Object?>;
  }
}
